#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int u, v;
    int w;
} Edge;

typedef struct {
    int parent;
    int size;
} DSU;

static int cmp_desc(const void *a, const void *b) {
    const Edge *x = (const Edge *)a;
    const Edge *y = (const Edge *)b;
    if (x->w != y->w) return (y->w - x->w);
    return 0;
}

static int find_root(DSU *dsu, int x) {
    while (dsu[x].parent != x) {
        dsu[x].parent = dsu[dsu[x].parent].parent;
        x = dsu[x].parent;
    }
    return x;
}

static ll unite(DSU *dsu, int a, int b, int w) {
    a = find_root(dsu, a);
    b = find_root(dsu, b);
    if (a == b) return 0;

    if (dsu[a].size < dsu[b].size) {
        int t = a; a = b; b = t;
    }

    ll sa = dsu[a].size;
    ll sb = dsu[b].size;

    dsu[b].parent = a;
    dsu[a].size += dsu[b].size;

    return (ll)w * sa * sb;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    Edge *edges = (Edge *)malloc(sizeof(Edge) * m);
    for (int i = 0; i < m; i++) {
        scanf("%d %d %d", &edges[i].u, &edges[i].v, &edges[i].w);
        edges[i].u--;
        edges[i].v--;
    }

    qsort(edges, m, sizeof(Edge), cmp_desc);

    DSU *dsu = (DSU *)malloc(sizeof(DSU) * n);
    for (int i = 0; i < n; i++) {
        dsu[i].parent = i;
        dsu[i].size = 1;
    }

    ll ans = 0;
    for (int i = 0; i < m; i++) {
        ans += unite(dsu, edges[i].u, edges[i].v, edges[i].w);
    }

    printf("%lld\n", ans);

    free(edges);
    free(dsu);
    return 0;
}

