import java.io.*;
import java.util.*;

/*
We process edges in descending order of friendliness.
At any threshold w, consider the graph formed by edges with value >= w.
For any connected component of size s in this graph, if we invite exactly those s rabbits,
each rabbit has minimal friendliness at least w to the rest through the party condition
used by the original problem, so the achievable score is s * w.
Thus while uniting components in descending edge order, we track the maximum:
    answer = max(answer, size(component) * current_edge_weight)

This is the standard DSU-on-sorted-edges solution.

Input format assumed:
N M
a1 b1 c1
...
aM bM cM

Output:
maximum satisfaction score

Uses long for safety.
*/
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int u, v;
        long w;

        Edge(int u, int v, long w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }
    }

    static class DSU {
        int[] parent;
        int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        int union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return a;
            if (size[a] < size[b]) {
                int t = a;
                a = b;
                b = t;
            }
            parent[b] = a;
            size[a] += size[b];
            return a;
        }

        int compSize(int x) {
            return size[find(x)];
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n;
        int m;
        try {
            n = fs.nextInt();
            m = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        Edge[] edges = new Edge[m];
        for (int i = 0; i < m; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            long c = fs.nextLong();
            edges[i] = new Edge(a, b, c);
        }

        Arrays.sort(edges, (e1, e2) -> Long.compare(e2.w, e1.w));

        DSU dsu = new DSU(n);
        long ans = 0;

        int i = 0;
        while (i < m) {
            int j = i;
            long w = edges[i].w;

            while (j < m && edges[j].w == w) {
                dsu.union(edges[j].u, edges[j].v);
                j++;
            }

            while (i < j) {
                int root = dsu.find(edges[i].u);
                ans = Math.max(ans, (long) dsu.size[root] * w);
                i++;
            }
        }

        System.out.println(ans);
    }
}
